import { SwipeToast } from "solen-design/react";

const [open, setOpen] = useState(true);

<SwipeToast
  title="File archived"
  description="Drag the card down to dismiss it"
  open={open}
  onClose={() => setOpen(false)}
  actionLabel="Undo"
  onAction={() => console.log("undo")}
  background="#27272a"
  fuseColor="#f5a524"
  duration={4000}
  fuse="bottom"
  swipeDistance={40}
  settleBounce={0.2}
  slideMs={400}
  pauseOnHover={true}
/>
